    # Hand-written: Alembic can't autogenerate these.
    # 1) No double booking: an employee can't have two active bookings whose
    #    [starts_at, blocked_until) ranges overlap. Enforced by PostgreSQL itself.
    op.execute(
        """
        ALTER TABLE bookings ADD CONSTRAINT bookings_no_overlap
        EXCLUDE USING gist (
            employee_id WITH =,
            tstzrange(starts_at, blocked_until, '[)') WITH &&
        ) WHERE (status IN ('pending', 'confirmed', 'in_progress'))
        """
    )
    # 2) An employee's weekly intervals on the same weekday must not overlap.
    op.execute(
        """
        ALTER TABLE employee_schedules ADD CONSTRAINT employee_schedules_no_overlap
        EXCLUDE USING gist (
            employee_id WITH =,
            weekday WITH =,
            tsrange('2000-01-01'::date + starts_local, '2000-01-01'::date + ends_local) WITH &&
        )
        """
    )


